begin;
create table public.marketplace_thread_bindings(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),account_id uuid not null references public.founder_accounts(id),counterparty_id uuid not null references public.counterparties(id),thread_key text not null,profile_hash text not null check(profile_hash~'^[a-f0-9]{64}$'),created_at timestamptz not null default clock_timestamp(),unique(mission_id,account_id,counterparty_id,thread_key,profile_hash));
alter table public.marketplace_thread_bindings enable row level security;alter table public.marketplace_thread_bindings force row level security;create policy mission_scope on public.marketplace_thread_bindings using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id));create trigger immutable_row before update or delete on public.marketplace_thread_bindings for each row execute function private.immutable_row();create trigger ledger_revision after insert on public.marketplace_thread_bindings for each row execute function private.record_ledger_revision();grant select on public.marketplace_thread_bindings to founder_role,lead_role,specialist_role,policy_role;
create function public.register_marketplace_thread(p_mission uuid,p_account uuid,p_party uuid,p_thread text,p_hash text)returns void language plpgsql security definer set search_path=''as $$begin
 perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);
 if p_thread!~'^[A-Za-z0-9_.:-]{1,160}$'or p_hash!~'^[a-f0-9]{64}$'or not exists(select from public.missions m join public.founder_accounts a on a.founder_id=m.founder_id join public.counterparties c on c.founder_id=m.founder_id where m.id=p_mission and a.id=p_account and a.provider='browserbase'and c.id=p_party and not c.opt_out)then raise exception 'validation: founder-owned marketplace account and recipient required';end if;
 insert into public.marketplace_thread_bindings(mission_id,account_id,counterparty_id,thread_key,profile_hash)values(p_mission,p_account,p_party,p_thread,p_hash)on conflict do nothing;
end$$;
create function public.check_marketplace_thread(p_mission uuid,p_account uuid,p_party uuid,p_thread text,p_hash text)returns boolean language plpgsql security definer set search_path=''as $$begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);
 return exists(select from public.marketplace_thread_bindings b join public.founder_accounts a on a.id=b.account_id where b.mission_id=p_mission and b.account_id=p_account and b.counterparty_id=p_party and b.thread_key=p_thread and b.profile_hash=p_hash and b.created_at>clock_timestamp()-interval'30 days'and a.status='connected'and not exists(select from public.account_revocations r where r.account_id=a.id));
end$$;
create function public.record_marketplace_outbound(p_mission uuid,p_party uuid,p_reference text,p_body text,p_translation text)returns uuid language plpgsql security definer set search_path=''as $$declare receipt public.provider_receipts;a public.effect_authorizations;thread uuid;message uuid;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(jsonb_build_object('body',p_body,'translation',p_translation));
 select r.*into strict receipt from public.provider_receipts r join public.effect_authorizations authz on authz.id=r.authorization_id where r.mission_id=p_mission and r.provider='browserbase'and r.provider_reference=p_reference and r.operation='marketplace_message'and authz.intent->>'counterpartyId'=p_party::text;select*into strict a from public.effect_authorizations where id=receipt.authorization_id;
 if not exists(select from public.artifact_versions v where v.id=(a.intent->>'artifactVersionId')::uuid and v.mission_id=p_mission and v.content->'payload'->>'text'=p_body and v.content->'payload'->>'translation'=p_translation and left(p_reference,length('alibaba:'||(v.content->'payload'->>'threadId')||':'))='alibaba:'||(v.content->'payload'->>'threadId')||':')then raise exception 'invariant_violation: marketplace message differs from its immutable receipt source';end if;
 select id into message from public.messages where mission_id=p_mission and receipt_id=receipt.id and direction='outbound';if message is not null then return message;end if;
 select id into thread from public.threads where mission_id=p_mission and counterparty_id=p_party order by created_at limit 1;if thread is null then insert into public.threads(mission_id,counterparty_id)values(p_mission,p_party)returning id into thread;end if;
 insert into public.messages(mission_id,thread_id,channel,direction,original,translation,provider_id,mandate_id,approval_id,receipt_id)values(p_mission,thread,'marketplace','outbound',p_body,p_translation,p_reference,a.mandate_id,a.approval_id,receipt.id)returning id into message;return message;
end$$;
create function public.record_marketplace_inbound(p_mission uuid,p_account uuid,p_party uuid,p_thread text,p_hash text,p_session uuid,p_messages jsonb)returns integer language plpgsql security definer set search_path=''as $$declare item jsonb;thread uuid;message uuid;reference text;inserted integer:=0;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);if not public.check_marketplace_thread(p_mission,p_account,p_party,p_thread,p_hash)or p_session is null or jsonb_typeof(p_messages)is distinct from'array'or jsonb_array_length(p_messages)>500 then raise exception 'validation: current registered marketplace poll required';end if;
 select id into thread from public.threads where mission_id=p_mission and counterparty_id=p_party order by created_at limit 1;if thread is null then insert into public.threads(mission_id,counterparty_id)values(p_mission,p_party)returning id into thread;end if;
 for item in select value from jsonb_array_elements(p_messages)loop
  if item->>'direction'<>'inbound'then continue;end if;if coalesce(length(item->>'messageId'),0)not between 1 and 160 or coalesce(length(item->>'text'),0)not between 1 and 10000 then raise exception 'validation: bounded marketplace message required';end if;perform private.assert_safe_content(item);
  reference:='alibaba:'||p_thread||':'||(item->>'messageId');message:=null;
  insert into public.messages(mission_id,thread_id,channel,direction,original,provider_id)values(p_mission,thread,'marketplace','inbound',item->>'text',reference)on conflict(mission_id,channel,provider_id)where direction='inbound'and provider_id is not null do nothing returning id into message;
  if message is not null then inserted:=inserted+1;perform public.append_evidence(p_mission,'supply','marketplace_reply','claimed',jsonb_build_object('messageId',message,'counterpartyId',p_party,'threadKey',p_thread,'browserSessionId',p_session,'text',item->>'text'),'message',message::text);insert into public.outbox(mission_id,type,payload)values(p_mission,'message.received',jsonb_build_object('messageId',message,'channel','marketplace'));
   if lower(trim(item->>'text'))in('stop','unsubscribe','توقف','إيقاف')then insert into public.counterparty_optouts(mission_id,counterparty_id,source)values(p_mission,p_party,'message:'||reference)on conflict(counterparty_id)do nothing;end if;
  end if;
 end loop;return inserted;
end$$;
revoke all on function public.register_marketplace_thread(uuid,uuid,uuid,text,text),public.check_marketplace_thread(uuid,uuid,uuid,text,text),public.record_marketplace_outbound(uuid,uuid,text,text,text),public.record_marketplace_inbound(uuid,uuid,uuid,text,text,uuid,jsonb)from public;
grant execute on function public.register_marketplace_thread(uuid,uuid,uuid,text,text)to founder_role;
grant execute on function public.check_marketplace_thread(uuid,uuid,uuid,text,text),public.record_marketplace_outbound(uuid,uuid,text,text,text),public.record_marketplace_inbound(uuid,uuid,uuid,text,text,uuid,jsonb)to policy_role;
create table public.marketplace_poll_attempts(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),account_id uuid not null references public.founder_accounts(id),counterparty_id uuid not null references public.counterparties(id),thread_key text not null,period_key text not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,period_key));
alter table public.marketplace_poll_attempts enable row level security;alter table public.marketplace_poll_attempts force row level security;create policy mission_scope on public.marketplace_poll_attempts using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id));create trigger immutable_row before update or delete on public.marketplace_poll_attempts for each row execute function private.immutable_row();grant select on public.marketplace_poll_attempts to policy_role;
create function public.claim_marketplace_poll(p_mission uuid,p_account uuid,p_party uuid,p_thread text,p_hash text,p_minutes integer,p_key text)returns boolean language plpgsql security definer set search_path=''as $$begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);
 if p_minutes not between 15 and 1440 or p_key!~'^[a-f0-9]{64}$'or not public.check_marketplace_thread(p_mission,p_account,p_party,p_thread,p_hash)then raise exception 'validation: bounded registered marketplace poll required';end if;
 if exists(select from public.marketplace_poll_attempts where mission_id=p_mission and account_id=p_account and counterparty_id=p_party and thread_key=p_thread and created_at>clock_timestamp()-make_interval(mins=>p_minutes))then return false;end if;
 insert into public.marketplace_poll_attempts(mission_id,account_id,counterparty_id,thread_key,period_key)values(p_mission,p_account,p_party,p_thread,p_key)on conflict do nothing;return found;
end$$;
revoke all on function public.claim_marketplace_poll(uuid,uuid,uuid,text,text,integer,text)from public;grant execute on function public.claim_marketplace_poll(uuid,uuid,uuid,text,text,integer,text)to policy_role;
-- A concurrent identical send may share its one held browser-seconds budget;
-- the durable effect claim still permits only one provider invocation. This
-- avoids a non-owning waiter consuming the effect and failing before the owner.
create function public.ensure_marketplace_budget(p_mission uuid,p_key text,p_units bigint)returns boolean language plpgsql security definer set search_path=''as $$declare reservation public.service_reservations;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);select*into reservation from public.service_reservations where mission_id=p_mission and task_key=p_key;
 if found then return reservation.provider='browserbase'and reservation.maximum_units=p_units and not exists(select from public.service_usage_events e where e.reservation_id=reservation.id);end if;
 return public.reserve_service_budget(p_mission,p_key,'browserbase',p_units);
end$$;
revoke all on function public.ensure_marketplace_budget(uuid,text,bigint)from public;grant execute on function public.ensure_marketplace_budget(uuid,text,bigint)to policy_role;
commit;
